#
# Double-click (or `sh iniciar.sh`): sets things up the first time and opens the interface.
# Always uses `python -m ...`: never an executable generated by pip. It only touches this folder and the local folder.

cd "$(dirname "$0")" || exit 1

DOWNLOAD_URL="https://www.python.org/downloads/"
VENV_PY=".venv/bin/python"
MARK=".venv/.maf-ready"
LOCAL_DIR_USED="${LOCAL_DIR:-.local}"
START_FILE="$LOCAL_DIR_USED/primer-recorrido-inicio.txt"
export PIP_DISABLE_PIP_VERSION_CHECK=1

wait_key() {
    printf 'Press Enter to close this window. '
    read -r _ || true
}

fail() {
    echo "Could not finish: $1"
    wait_key
    exit 1
}

sha_of_requirements() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum requirements.txt | cut -d ' ' -f 1
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 requirements.txt | cut -d ' ' -f 1
    elif command -v openssl >/dev/null 2>&1; then
        openssl dgst -sha256 requirements.txt | sed 's/^.*= *//'
    else
        return 1
    fi
}

find_python() {
    for candidate in python3.14 python3.13 python3.12 python3; do
        if command -v "$candidate" >/dev/null 2>&1 &&
            "$candidate" -c 'import sys; sys.exit(0 if (3, 12) <= sys.version_info[:2] <= (3, 14) else 1)' >/dev/null 2>&1; then
            echo "$candidate"
            return 0
        fi
    done
    return 1
}

no_python() {
    echo "I could not find Python on this computer."
    echo "I will open the download page: $DOWNLOAD_URL"
    echo "Download \"Python 3.13\" (the latest stable version between 3.12 and 3.14)."
    echo "Install it and open this file again. Nothing was created or changed."
    if [ "$(uname -s 2>/dev/null)" = "Darwin" ]; then
        open "$DOWNLOAD_URL" >/dev/null 2>&1 || echo "Open this address in your browser: $DOWNLOAD_URL"
    else
        xdg-open "$DOWNLOAD_URL" >/dev/null 2>&1 || echo "Open this address in your browser: $DOWNLOAD_URL"
    fi
    wait_key
    exit 1
}

echo "Multi-Agent Framework: start"

if [ ! -f "$VENV_PY" ]; then
    SYSTEM_PY="$(find_python)" || no_python
fi

# 1. The start time, written once (never overwritten).
if [ ! -f "$START_FILE" ]; then
    mkdir -p "$LOCAL_DIR_USED" || fail "could not create the local folder ($LOCAL_DIR_USED)."
    date +%Y-%m-%dT%H:%M:%S%z | sed 's/\([0-9][0-9]\)$/:\1/' >"$START_FILE" ||
        fail "could not write down the start time."
fi

# 3. The environment.
if [ ! -f "$VENV_PY" ]; then
    echo "[1/4] Creating the environment (first time only)..."
    "$SYSTEM_PY" -m venv .venv || fail "step 1 of 4, creating the environment (.venv)."
    [ -f "$VENV_PY" ] || fail "step 1 of 4, the environment is not ready."
fi

# 4 to 6. Dependencies, database and marker.
WANTED="$(sha_of_requirements)" || fail "could not compute the fingerprint of requirements.txt."
CURRENT=""
[ -f "$MARK" ] && CURRENT="$(cat "$MARK")"
if [ "$CURRENT" != "$WANTED" ]; then
    echo "[2/4] Installing the dependencies (this can take a few minutes)..."
    "$VENV_PY" -m pip install -r requirements.txt || fail "step 2 of 4, installing the dependencies."
    echo "[3/4] Preparing the database..."
    "$VENV_PY" -m multiagent init || fail "step 3 of 4, preparing the database."
    printf '%s\n' "$WANTED" >"$MARK" || fail "could not save the installation marker."
fi

# 7. The interface.
echo "[4/4] Opening the interface. To close it, close this window or press Ctrl+C."
"$VENV_PY" -m multiagent gui --launcher || fail "step 4 of 4, opening the interface."
